{
  "name": "@yaak/faker",
  "displayName": "Faker",
  "description": "A template tag to generate fake data using FakerJS",
  "private": true,
  "version": "1.0.0",
  "repository": "https://github.com/mountain-loop/yaak-plugin-faker",
  "scripts": {
    "build": "yaakcli build",
    "dev": "yaakcli dev"
  },
  "homepage": "https://github.com/mountain-loop/yaak-plugin-faker",
  "devDependencies": {
    "@types/node": "^20.14.9",
    "@yaakapp/cli": "^0.2.6",
    "typescript": "^5.5.2",
    "vitest": "3.0.5"
  },
  "dependencies": {
    "@faker-js/faker": "^9.8.0",
    "@yaakapp/api": "^0.6.4"
  }
}

import {faker} from '@faker-js/faker';
import {PluginDefinition} from '@yaakapp/api';

const modules = [
  "airline",
  "animal",
  "color",
  "commerce",
  "company",
  "database",
  "date",
  "finance",
  "git",
  "hacker",
  "image",
  "internet",
  "location",
  "lorem",
  "person",
  "music",
  "number",
  "phone",
  "science",
  "string",
  "system",
  "vehicle",
  "word",
];

export const plugin: PluginDefinition = {
  templateFunctions: modules.flatMap(name => {
    // @ts-ignore
    const module = faker[name];
    return Object.keys(module).filter(n => n !== 'faker').map(functionName => ({
      name: ['faker', name, functionName].join('.'),
      args: [],
      async onRender(_ctx, _args) {
        const fakerFunction = module[functionName];
        const result = fakerFunction();
        if (typeof result !== 'string') {
          return JSON.stringify(result);
        }
        return result;
      },
    }));
  }),
};
